command_result.command:
cd /tmp/v && cat > app.c <<'EOF'
#include <isodur/isodur.h>
#include <stdio.h>
int main(void){isodur_t d; isodur_from_ms(5400000,&d); char b[64]; isodur_format(&d,ISODUR_STYLE_ISO,0,b,64); printf("%s %s\n",b,isodur_version()); return 0;}
EOF
for v in lib64 ds def; do P=/tmp/v/$v/prefix; export PKG_CONFIG_PATH=$(echo $P/lib*/pkgconfig); echo == $v; cc app.c -o a1 $(pkg-config --cflags --libs isodur) 2>&1 | tail -3; LD_LIBRARY_PATH=$(dirname $PKG_CONFIG_PATH) ./a1; cc app.c -o a2 $(pkg-config --cflags --static --libs isodur) && ./a2; $P/bin/durfmt PT90M P1Y2M; $P/bin/isodur fmt --style long P1Y2M3DT4H; $P/bin/durfmt --style long PT3H; done; unset PKG_CONFIG_PATH; rm -f /tmp/v/*.c.o

cd /app && ls -a && cat > STATUS.json <<'EOF'
{"status": "success", "summary": "Fixed configure.ac (version read from VERSION, BUILD_TOOL conditional in both cases, data/Makefile, no unexpanded ISODUR_DATADIR) and the Makefile.am files and isodur.pc.in (include paths for generated headers, header/pkgconfig/lib64 install dirs, -version-info and -export-symbols-regex, LIBM, durfmt link with DESTDIR, VPATH test cases, dist contents). Verified default, --disable-shared, lib64/datarootdir, --disable-tool and changed VERSION/interface builds, distcheck and tarball rebuild; with a changed VERSION only the hardcoded tests/cases/version.out check differs, as expected."}
EOF
